let renderer;
let projector;
let projectionShader;
let mMatrix = new p5.Matrix();

let pg;
let pgShader;

function setup() {
	renderer = createCanvas(1112, 834, WEBGL);
	pixelDensity(1);

	projector = new p5.Camera(renderer);
	projector.camera(0, 0, (height/4.0) / tan(PI*30.0 / 180.0), 0, 0, 0, 0, 1, 0);
	projector.perspective(PI*2/3, 1.0, 0.1, 100);

	projectionShader = createShader(projectionVert, projectionFrag);
	shader(projectionShader);
	projectionShader.setUniform('uTexPMatrix', projector.projMatrix.mat4);
	projectionShader.setUniform('uTexVMatrix', projector.cameraMatrix.mat4);

	pg = createGraphics(width, height, WEBGL);
	pgShader = pg.createShader(pgVert, pgFrag);
	pg.shader(pgShader);
	pgShader.setUniform('uColor1', [51/255,  99/255, 118/255]);
	pgShader.setUniform('uColor2', [52/255, 177/255, 166/255]);
	pgShader.setUniform('uColor3', [55/255, 220/255, 204/255]);
	pgShader.setUniform('uStroke', [ 42/255,  42/255,  42/255]);
	pgShader.setUniform('uSeed', random(10000, 100000));
}

function draw() {
	background(255);
	pgShader.setUniform('uTime', millis()/10.0);
	pg.rect(-width/2, -height/2, width, height);
	projectionShader.setUniform('uTexture', pg);
	stroke(0);
	mMatrix = p5.Matrix.identity();
	mMatrix.rotateX(millis()/1000.0);
	mMatrix.rotateY(millis()/1000.0);
	mMatrix.scale(200, 200, 200);
	projectionShader.setUniform('uModelMatrix', mMatrix.mat4);
	push();
	rotateX(millis()/1000.0);
	rotateY(millis()/500.0);
	noStroke();
	sphere(250);
	ambientMaterial(0,2);
	sphere(251);
	pop();
	noStroke();
	mMatrix = p5.Matrix.identity();
	mMatrix.translate([0, 0, -400]);
	mMatrix.scale(width*2, height*2, 1);
	projectionShader.setUniform('uModelMatrix', mMatrix.mat4);
	push();
	translate(0, 0, -400);
	plane(width*2, height*2, 1);
	pop();
}

let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save('pix.jpg');
    lapse = millis();
  }
}

// === Tab: projectionShader ===
let projectionVert = `
attribute vec3 aPosition;
attribute vec4 aVertexColor;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

uniform mat4 uModelMatrix;
uniform mat4 uTexVMatrix;
uniform mat4 uTexPMatrix;

varying vec2 vTexCoord;
varying vec3 vDiffuseColor;
varying vec3 vSpecularColor;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
	vec4 viewModelPosition = uModelViewMatrix * positionVec4; 
  gl_Position = uProjectionMatrix * viewModelPosition;

	vec4 texPosition = uTexPMatrix * uTexVMatrix * uModelMatrix * positionVec4;
	vTexCoord = texPosition.xy / texPosition.w * vec2(0.5, -0.5) + 0.5;		// ? : zで割るのかwで割るのか
}
`;


let projectionFrag = `
precision highp float;

uniform vec4 uMaterialColor;
uniform sampler2D uTexture;		

varying vec2 vTexCoord;
varying vec3 vDiffuseColor;
varying vec3 vSpecularColor;

void main(void) {
	if (min(vTexCoord.x, vTexCoord.y) > 0.0 && max(vTexCoord.x, vTexCoord.y) < 1.0) {
		gl_FragColor = texture2D(uTexture, vTexCoord);
	} else {
  	gl_FragColor = uMaterialColor;
	}
}
`;

// === Tab: pgShader ===
let pgVert = `
precision highp float;

attribute vec3 aPosition;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
}
`;



let pgFrag = `
precision highp float;

#define PI 3.141592653589793

uniform vec3 uColor1;
uniform vec3 uColor2;
uniform vec3 uColor3;
uniform vec3 uStroke;

uniform float uSeed;
uniform float uTime;

float rand2D(vec2 _p) {
	return fract(sin(dot(_p.xy ,vec2(12.9898,78.233))) * uSeed);
}

float grad(vec2 _p1, vec2 _p2) {
	float theta = 2.0 * PI * rand2D(_p1);
	vec2 v1 = vec2(cos(theta), sin(theta)) / sqrt(2.0);
	vec2 v2 = _p2 - _p1;
	return dot(v1, v2);
}

// パーリンノイズ
float perlin(vec2 _p, float _size) {
	vec2 uv = _p / _size;
	float xf = smoothstep(0.0, 1.0, fract(uv.x));
	float yf = smoothstep(0.0, 1.0, fract(uv.y));
	float x0 = floor(uv.x);
	float x1 = floor(uv.x) + 1.0;
	float y0 = floor(uv.y);
	float y1 = floor(uv.y) + 1.0;

	float n1 = mix(grad(vec2(x0, y0), uv), grad(vec2(x1, y0), uv), xf);
	float n2 = mix(grad(vec2(x0, y1), uv), grad(vec2(x1, y1), uv), xf);

	return (mix(n1, n2, yf) + 1.0) / 2.0;	
}

float octavePerlin(vec2 _p, float _size, float persistence) {
	float total = 0.0;
	float max = 0.0;
	float size = _size;
	float amplitude = 1.0;
	const int octaves = 10;

	for (int i=0; i<octaves; i++) {
		total += amplitude * perlin(_p, size);
		max += amplitude;
		size /= 2.0;
		amplitude *= persistence;
	}

	return total / max;
}

void main(void) {
	float amp = octavePerlin(gl_FragCoord.xy + vec2(0.0, uTime), 100.0, 0.2);

	if (amp > 0.535) {
		gl_FragColor = vec4(uColor1, 1.0);
	} else if (amp > 0.53) {
		gl_FragColor = vec4(uStroke, 1.0);
	} else if (amp > 0.47) {
		gl_FragColor = vec4(uColor2, 1.0);
		if (mod(floor((gl_FragCoord.x+gl_FragCoord.y+uTime) / 2.0), 8.0) == 0.0) gl_FragColor = vec4(uStroke, 1.0);
	} else if (amp > 0.465) {
		gl_FragColor = vec4(uStroke, 1.0);
	} else {
		gl_FragColor = vec4(uColor3, 1.0);
		if (mod(floor((gl_FragCoord.x+gl_FragCoord.y+uTime) / 2.0), 8.0) == 0.0 || mod(floor((gl_FragCoord.x+gl_FragCoord.y+uTime) / 2.0), 8.0) == 4.0) gl_FragColor = vec4(uStroke, 1.0);
	}
}
`;

